// Function (processa todos os itens)
// Entrada de cada item:
//   - it.binary.data.data (base64 do HTML do "imprimir-edital")  OU
//   - it.json.data (HTML em string)
// Saída: 1 item com os campos do edital. Horário é obrigatório.

const items = $input.all();
const out = [];

// @ts-ignore - Buffer é global no runtime do n8n
const B = (globalThis && globalThis.Buffer) ? globalThis.Buffer : Buffer;

function clean(s = "") {
  return s.replace(/<[^>]*>/g, " ")
          .replace(/&nbsp;?/g, " ")
          .replace(/\s+/g, " ")
          .trim();
}



for (const it of items) {
  // 1) Obter o HTML
  let html = "";
  const b64 = it.binary?.data?.data;
  if (b64) {
    // binário -> base64 -> latin1
    const buf = B.from(b64, "base64");
    html = buf.toString("latin1");
  } else if (typeof it.json?.data === "string") {
    // string -> reinterpretar como latin1 (corrige acentos trocados)
    html = B.from(it.json.data, "binary").toString("latin1");
  } else {
    out.push({ json: { error: "Sem HTML neste item (nem binário nem string)" } });
    continue;
  }

  // 2) Cabeçalho
  const Municipio = clean(html.match(/<b>\s*Munic[^:]*:\s*<\/b>\s*([^<]+)/i)?.[1] || "");

  const unidRaw = clean(html.match(/<b>\s*Unidade\s+de\s+Ensino:\s*<\/b>\s*([^<]+)/i)?.[1] || "");
  let EscolaCodigo = "", Escola = unidRaw;
  const mUE = unidRaw.match(/^(\d+)\s*-\s*(.*)$/);
  if (mUE) { EscolaCodigo = mUE[1]; Escola = mUE[2]; }

  const Data = html.match(/<b>\s*Data\s*:\s*<\/b>\s*([\d/]+)/i)?.[1] || "";

  // Horário (tolerante a "Horário"/"Hor�rio" e formatos 08 hora(s), 8h, 08:00)
  let HorarioTexto = clean(html.match(/<b>\s*Hor[^<]*?rio\s*:\s*<\/b>\s*([^<]+)/i)?.[1] || "");
  if (!HorarioTexto) {
    // fallback: pega texto logo após a tag <b>...Hor*rio:</b>
    const near = html.match(/Hor[^<]{0,10}rio\s*:\s*<\/b>\s*([^<]+)/i);
    if (near) HorarioTexto = clean(near[1]);
  }

  let Horario = "";
  {
    // "08 hora(s)" ou "8 hora(s)"
    const m1 = HorarioTexto.match(/\b(\d{1,2})\s*hora/i);
    // "8h" ou "8:00"
    const m2 = HorarioTexto.match(/\b(\d{1,2})(?:[:h](\d{2}))?\b/);
    let hh = null, mm = "00";
    if (m1) {
      hh = m1[1];
    } else if (m2) {
      hh = m2[1];
      if (m2[2]) mm = m2[2];
    }
    if (hh != null) Horario = `${String(hh).padStart(2, "0")}:${String(mm).padStart(2, "0")}`;
  }

  // Endereço
  const Endereco = clean(html.match(/<b>\s*Endere[^:]*:\s*<\/b>\s*([\s\S]*?)<\/td>/i)?.[1] || "");



  // 3) Primeira linha da tabela "Características da vaga"
  let Cargo="", Categoria="", Natureza="", Justificativa="", Conteudo="", Nivel="", Turno="", CargaHorariaRB="", CargaHorariaAEC="", PeriodoInicial="", PeriodoFinal="", Observacoes="";
  const row = html.match(/<table\s+class="tabela">[\s\S]*?<tr>[\s\S]*?<\/tr>\s*<tr>[\s\S]*?<\/tr>\s*<tr>([\s\S]*?)<\/tr>/i);
  if (row) {
    const tds = [...row[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map(m => clean(m[1]));
    Cargo            = tds[0] || "";
    Categoria        = tds[1] || "";
    Natureza         = tds[2] || "";
    Conteudo         = tds[4] || "";
    Nivel            = tds[5] || "";
    Turno            = tds[6] || "";
    CargaHorariaRB   = tds[7] || "";
    CargaHorariaAEC  = tds[8] || "";
    PeriodoInicial   = tds[9] || "";
    PeriodoFinal     = tds[10] || "";
    Observacoes      = tds[11] || "";
  }

  // 4) Validação obrigatória
  if (!HorarioTexto && !Horario) {
    out.push({ json: { error: "Horário não encontrado (edital)" } });
    continue;
  }

  function stripAccents(s='') {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
function norm(s='') {
  return stripAccents(String(s))
    .replace(/\s+/g,' ')
    .trim()
    .toUpperCase();
}
function toISODateBR(d='') {           // "dd/mm/aaaa" -> "aaaa-mm-dd"
  const m = String(d).match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : d;
}
function makeHash(s) {
  try {
    const crypto = require('crypto');
    return crypto.createHash('sha1').update(s).digest('hex').slice(0,16); // 16 hex = 64 bits
  } catch (e) {
    // fallback bem simples (djb2)
    let h = 5381;
    for (let i=0;i<s.length;i++) h = ((h<<5)+h) + s.charCodeAt(i);
    return (h>>>0).toString(16).padStart(8,'0');
  }
}

  const base = [
  norm(EscolaCodigo),
  norm(toISODateBR(Data)),   // "dd/mm/aaaa" -> "aaaa-mm-dd"
  norm(Horario),             // "HH:MM"
  norm(Cargo),
  norm(Categoria),
  norm(Natureza),
  norm(Turno),
  norm(Conteudo),
].join('|');

const UID = makeHash(base);


 out.push({
  json: {
    UID,                                  // <<<<<<
    EscolaCodigo, Escola, Municipio,
    Data, HorarioTexto, Horario, Endereco,
    Cargo, Categoria, Natureza, Conteudo, Nivel, Turno,
    CargaHorariaRB, CargaHorariaAEC, PeriodoInicial, PeriodoFinal, Observacoes,
    urlEdital: it.json?.urlEdital || ""
  }
});
}

return out.length ? out : [{ json: { error: "Nenhum item processado" } }];

function clean(s=''){
  return s.replace(/<[^>]*>/g,' ')
          .replace(/&nbsp;/g,' ')
          .replace(/\s+/g,' ')
          .trim();
}

const items = $input.all();    // <— em vez de $input.first()
const out = [];

for (const item of items) {
  // decodifica o HTML de CADA página
  let html = '';
  const b64 = item.binary?.data?.data;
  html = b64 ? Buffer.from(b64, 'base64').toString('latin1')
             : String(item.json?.data || '');

  const tbMatch = html.match(/<table[^>]*class="tabela\s+seletor"[^>]*>([\s\S]*?)<\/table>/i);
  if (!tbMatch) {
    out.push({ json: { error: 'Tabela não encontrada', page: item.json?.page } });
    continue;
  }

  const tb = tbMatch[1];
  const rows = [...tb.matchAll(/<tr>([\s\S]*?)<\/tr>/gi)];
  for (const r of rows) {
    const tds = [...r[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map(m => m[1]);
    if (tds.length < 7) continue;

    const Regional  = clean(tds[0]);
    const Municipio = clean(tds[1]);
    const Escola    = clean(tds[2]);
    const Cargo     = clean(tds[3]);
    const Categoria = clean(tds[4]);
    const Conteudo  = clean(tds[5]);

    const urlEdital = (r[1].match(/<a[^>]*class="icone\s+popup"[^>]*\surl="([^"]+)"/i)?.[1]) || '';
    if (!urlEdital) continue;

    out.push({ json: { page: item.json?.page, Regional, Municipio, Escola, Cargo, Categoria, Conteudo, urlEdital }});
  }
}

return out.length ? out : [{ json: { error: 'Sem itens' } }];

