// Entrada: item.binary.data (base64 do HTML, ISO-8859-1)
// Saída: N itens: { json: { page: 1 } }, { json: { page: 2 } }, ...

function getHtml(item) {
  const b64 = item.binary?.data?.data;
  if (b64) return Buffer.from(b64, 'base64').toString('latin1');
  return String(item.json?.data || '');
}

const html = getHtml($input.first());

// 1) Tenta "Página X de Y"
let total = 1;
const m = html.match(/Página\s+(\d+)\s+de\s+(\d+)/i);
if (m) {
  total = parseInt(m[2], 10) || 1;
} else {
  // 2) Fallback: pega o MAIOR /page:K nos links do paginador
  const pages = [...html.matchAll(/\/page:(\d+)/gi)].map(x => parseInt(x[1], 10));
  if (pages.length) total = Math.max(...pages);
}

// Gera 1..total
return Array.from({ length: total }, (_, i) => ({ json: { page: i + 1 } }));
